/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_contacts, create_contact))
        .routes(routes!(list_most_consulted_contacts))
        .routes(routes!(get_contact, update_contact, delete_contact))
        .routes(routes!(record_contact_view))
        .routes(routes!(move_contact))
        .routes(routes!(get_contact_avatar, set_contact_avatar, delete_contact_avatar))
        .routes(routes!(list_contact_quick_facts, create_contact_quick_fact))
        .routes(routes!(update_contact_quick_fact, delete_contact_quick_fact))
        .routes(routes!(list_contact_feed_items))
}
